import sys
from collections import defaultdict
def main():
    data = sys.stdin.buffer.read().split(b'\n')
    d = defaultdict(list)
    for line in data[1:]:
        if line:
            p = line.split(b',')
            d[p[1]].append(p[2])
    import math
    for k in sorted(d):
        print("%s %.2f" % (k.decode(), math.fsum(map(float, d[k]))))
main()

import sys
from collections import defaultdict
def main():
    d = defaultdict(float)
    data = sys.stdin.buffer.read().split(b'\n')
    for line in data[1:]:
        if line:
            _, c, v = line.split(b',')
            d[c] += float(v)
    for k in sorted(d):
        print("%s %.2f" % (k.decode(), d[k]))
main()

import sys
from collections import defaultdict
def main():
    d = defaultdict(float)
    for line in sys.stdin.buffer.readlines()[1:]:
        p = line.split(b',')
        d[p[1]] += float(p[2])
    for k in sorted(d):
        print("%s %.2f" % (k.decode(), d[k]))
main()
